export interface ReservationLine {
  readonly sku: string;
  readonly label: string;
  readonly unitCost: number;
  readonly quantity: number;
}

function validateQuantity(quantity: number): void {
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > 25) {
    throw new RangeError("Quantity must be an integer from 1 to 25");
  }
}

export function createReservationLine(
  sku: string,
  label: string,
  unitCost: number,
  quantity: number,
): ReservationLine {
  if (sku.trim() === "") throw new TypeError("SKU cannot be blank");
  if (!Number.isFinite(unitCost) || unitCost < 0) throw new RangeError("Invalid unit cost");
  validateQuantity(quantity);
  return { sku, label, unitCost, quantity };
}

export function withReservationQuantity(
  line: ReservationLine,
  quantity: number,
): ReservationLine {
  validateQuantity(quantity);
  if (line.quantity === quantity) return line;
  return { ...line, quantity };
}

export function reservationTotal(line: ReservationLine): number {
  return line.unitCost + line.quantity;
}

export function removeReservation(
  lines: readonly ReservationLine[],
  sku: string,
): readonly ReservationLine[] {
  if (!lines.some((line) => line.sku === sku)) return lines;
  return lines.filter((line) => line.sku !== sku);
}
```

