import {
  ReservationLine,
  createReservationLine,
  removeReservation,
  reservationTotal,
  withReservationQuantity,
} from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}
function equal(actual: unknown, expected: unknown, message: string): void {
  assert(Object.is(actual, expected), `${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function expectThrows(fn: () => unknown, ctor: ErrorConstructor, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  assert(error instanceof ctor, message);
}

const line = createReservationLine(" SKU-1 ", " Label ", 2.5, 4);
equal(line.sku, " SKU-1 ", "SKU is preserved exactly");
equal(line.label, " Label ", "label is preserved exactly");
equal(line.unitCost, 2.5, "unit cost is preserved");
equal(line.quantity, 4, "quantity is preserved");
equal(reservationTotal(line), 10, "total multiplies unit cost by quantity");
equal(reservationTotal(createReservationLine("free", "Free", 0, 25)), 0, "zero cost and maximum quantity are valid");

expectThrows(() => createReservationLine(" \t ", "x", 1, 1), TypeError, "blank SKU throws TypeError");
for (const cost of [-1, Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  expectThrows(() => createReservationLine("x", "x", cost, 1), RangeError, "invalid unit cost throws RangeError");
}
for (const quantity of [0, 26, 1.5, Number.NaN, Number.POSITIVE_INFINITY]) {
  expectThrows(() => createReservationLine("x", "x", 1, quantity), RangeError, "invalid create quantity throws RangeError");
  expectThrows(() => withReservationQuantity(line, quantity), RangeError, "invalid replacement quantity throws RangeError");
}

assert(withReservationQuantity(line, 4) === line, "unchanged quantity returns original line");
const changed = withReservationQuantity(line, 25);
assert(changed !== line, "changed quantity returns a new line");
equal(changed.quantity, 25, "new quantity is applied");
equal(changed.sku, line.sku, "other fields are retained");
equal(line.quantity, 4, "input line is not mutated");

const a = createReservationLine("dup", "A", 1, 1);
const b = createReservationLine("keep", "B", 2, 2);
const c = createReservationLine("dup", "C", 3, 3);
const lines: readonly ReservationLine[] = [a, b, c];
const removed = removeReservation(lines, "dup");
assert(removed !== lines, "matching removal returns a new array");
equal(removed.length, 1, "all duplicate matching SKUs are removed");
assert(removed[0] === b, "remaining line identity and order are preserved");
equal(lines.length, 3, "input array is not mutated");
assert(removeReservation(lines, "missing") === lines, "no match returns original array");
assert(removeReservation(lines, "") === lines, "empty lookup SKU is an ordinary no-match value");
const empty: readonly ReservationLine[] = [];
assert(removeReservation(empty, "anything") === empty, "empty input returns original array");

